from z3 import *

def solve_social_golfers(num_weeks, num_golfers, num_groups, group_size):
    # Variables: x[w][p] is the group of golfer p in week w
    x = [[Int(f"x_{w}_{p}") for p in range(num_golfers)] for w in range(num_weeks)]

    solver = Solver()

    # Each golfer is in a group 0..num_groups-1
    for w in range(num_weeks):
        for p in range(num_golfers):
            solver.add(x[w][p] >= 0, x[w][p] < num_groups)

    # Each group has exactly group_size players
    for w in range(num_weeks):
        for g in range(num_groups):
            solver.add(Sum([If(x[w][p] == g, 1, 0) for p in range(num_golfers)]) == group_size)

    # No pair of golfers meets more than once
    for p1 in range(num_golfers):
        for p2 in range(p1 + 1, num_golfers):
            solver.add(Sum([If(x[w][p1] == x[w][p2], 1, 0) for w in range(num_weeks)]) <= 1)

    if solver.check() == sat:
        model = solver.model()
        result = []
        for w in range(num_weeks):
            for p in range(num_golfers):
                result.append(model.evaluate(x[w][p]).as_long())
        return result
    else:
        return None

