def verify_solution(num_weeks, num_golfers, num_groups, group_size, solution):
    if len(solution) != num_weeks * num_golfers:
        return False, "Incorrect length"

    # Check group sizes
    for w in range(num_weeks):
        for g in range(num_groups):
            count = 0
            for p in range(num_golfers):
                if solution[w * num_golfers + p] == g:
                    count += 1
            if count != group_size:
                return False, f"Week {w}, Group {g} has {count} players, expected {group_size}"

    # Check pairs
    pairs = {}
    for w in range(num_weeks):
        for g in range(num_groups):
            group_members = [p for p in range(num_golfers) if solution[w * num_golfers + p] == g]
            for i in range(len(group_members)):
                for j in range(i + 1, len(group_members)):
                    p1, p2 = group_members[i], group_members[j]
                    pair = tuple(sorted((p1, p2)))
                    if pair in pairs:
                        return False, f"Pair {pair} met in week {pairs[pair]} and week {w}"
                    pairs[pair] = w
    return True, "Valid"

